const markInvoiceAdjustmentSending = `-- name: MarkInvoiceAdjustmentSending :execrows
UPDATE invoice_adjustments
SET status = 'SENDING',
    updated_at = $1,
    version = version + 1
WHERE id = $2
  AND status IN ('PENDING', 'SENDING')
`

type MarkInvoiceAdjustmentSendingParams struct {
	Now pgtype.Timestamptz `db:"now" json:"now"`
	ID  int64              `db:"id" json:"id"`
}

// G08 PENDING → SENDING（對應 operation Claim 成功的同一事務內連動）。
//
// 🔴 allowed-from **含 SENDING 自己**，理由與 ⑦ ClaimInvoiceRecheck 的候選述詞含
//
//	PROVIDER_STATUS_RECHECK 完全同源：少了它就是「把永久旗標寫得更像 lease」。
//
//	走到這一句的人**已經持有 operation 的租約**（同一事務內 ops.Claim 成功在前），
//	所以自轉移不會製造第二個持有者 —— 併發保護在 operation 那一層，adjustment 只是跟著走。
//
//	少了 SENDING 的後果（dev 第 3 輪 INV58R3-ALW06 實測）：持有者在送出之後、
//	狀態寫回之前失敗（本例是 status_history 撞 22001 讓整個交易 rollback），
//	adjustment 停在 SENDING 而 operation 被退回 RETRY_SCHEDULED
//	⇒ 下一輪 claim 的 MarkSending rows=0 ⇒ ClaimForAllowanceAt 回 error
//	⇒ **整個 claim 交易 rollback，operation 狀態原地不動**
//	⇒ INV.op 每 10 秒重試一次、每次都失敗，**永久卡死**。
//	實測：next_attempt_at 過期 13 分鐘、約 80 次嘗試，兩列 updated_at 一動也沒動。
//
//	而 invoice_adjustment_stuck_rows 的述詞**刻意不含 SENDING**，理由寫的是
//	「那個有自己的執行者」—— 這一句就是那個執行者，它認不得 SENDING 時，
//	那句註解不成立，於是這種卡死在指標上**完全不存在**。
//
//	仍然拒絕其他狀態（COMPLETED／FAILED_*／CANCELLED／BLOCKED_*）：
//	那些才是「狀態機真的破了」，放行會讓 AMEGO 收到我方帳上不存在的折讓單。
func (q *Queries) MarkInvoiceAdjustmentSending(ctx context.Context, arg MarkInvoiceAdjustmentSendingParams) (int64, error) {
	result, err := q.db.Exec(ctx, markInvoiceAdjustmentSending, arg.Now, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

