//	重開成功 ⇒ 新件；REJECTED ⇒ 原件。折讓必須掛在生效中的發票上——掛在即將作廢的舊件上
//	是無效憑證，而 AMEGO 不會替我方檢查這件事。
func (q *Queries) RebindInvoiceAdjustmentAfterCorrection(ctx context.Context, arg RebindInvoiceAdjustmentAfterCorrectionParams) (int64, error) {
	result, err := q.db.Exec(ctx, rebindInvoiceAdjustmentAfterCorrection, arg.DocumentID, arg.Now, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

