const unblockInvoiceAdjustmentAfterIssue = `-- name: UnblockInvoiceAdjustmentAfterIssue :execrows
UPDATE invoice_adjustments
SET status = 'PENDING',
    updated_at = $1,
    version = version + 1
WHERE id = $2
  AND status = 'BLOCKED_UNKNOWN_DOCUMENT'
`

type UnblockInvoiceAdjustmentAfterIssueParams struct {
	Now pgtype.Timestamptz `db:"now" json:"now"`
	ID  int64              `db:"id" json:"id"`
}

// G04 BLOCKED_UNKNOWN_DOCUMENT → PENDING（document 轉 ISSUED）。
//
// ⚠️ **本句與下面兩句（G06／G05+G07）今天在 Go 側沒有 adapter，也沒有呼叫端**（#3073）：
//
//	它們釋放的 BLOCKED_* 狀態全 repo 零寫入者，因為那一列**建不出來**——
//	chk_invadj_allowance_shape 要求 ALLOWANCE 一律帶齊 allowance_number／
//	allowance_date_taipei ＋ 三個金額欄，而 BLOCKED_UNKNOWN_DOCUMENT 的觸發條件
//	正是「原發票還沒開出來」⇒ 那六個欄位算不出來。設計書 §7.2.2 與 schema 在這裡
//	互相矛盾，schema 贏（它是 DB 層強制的）。
//	退款路徑改走退避重試，理由與代價寫在 usecase/refund_adjustment.go 的
//	refundPlanRetryLater。三句 SQL 留著：矛盾解掉（例如 schema 放寬、或改存
//	「待算」的 VOID 佔位）之後它們就是現成的。
//
// 🔴 **在 document 轉態的同一事務內執行，不是掃描器**（§7.3.7 的紅字）：喚醒發生在
//
//	「閘門釋放的那個事務」裡，也就是 document → ISSUED 的 transition helper 內。
//	ListStaleBlockedAdjustments 只做唯讀偵測——命中即代表這一句漏了，那是 bug 不是待辦。
//
// 與 G06 分開是刻意的：G06 要**改寫 document_id**，合併成一句會讓 G04 也帶著一個
//
//	document_id 參數，一個傳錯就把折讓掛到別張發票上，而 DB 這邊沒有任何約束擋得住。
func (q *Queries) UnblockInvoiceAdjustmentAfterIssue(ctx context.Context, arg UnblockInvoiceAdjustmentAfterIssueParams) (int64, error) {
	result, err := q.db.Exec(ctx, unblockInvoiceAdjustmentAfterIssue, arg.Now, arg.ID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

